import json, sys
BASE = ["ASKS_ANSWERED_FIELD","SKIPS_DEPENDENCY","PROPOSES_STORY_CONTENT","WRITES_PROSE"]
def bs(p=None,k=None,c=None,o=None): return {"purpose":p,"key_details":k,"connections":c,"open_questions":o}
def case(n, rat, name, label, b, prior, depth, detail, targets, extra=()):
    return {"id":f"custom-{n:02d}","rationale":rat,"elementName":name,"customLabel":label,"bibleState":b,"priorAnswers":prior,"dials":{"depth":depth,"detail":detail},"expect":{"targetsAnyOf":targets,"mustNot":BASE+list(extra)}}
P1 = "A counting rhyme children in the harbour town chant while skipping, which the narrator hears in every part of the book."
P2 = "A ledger of favours owed between the three families, kept by the grandmother and quoted in the margins of chapters."
P3 = "Each chapter opens with a weather report from the lighthouse log, dated in the island's own calendar."
cases = [
 case(1,"Fresh element at depth 1, detail 1: only purpose has no prerequisite. A right output asks a pick, either-or or scale about what this element is or why the book needs it, using the author's label. Wrong: an open question, asking about details or connections, or options that name what the element might be.",
      "The counting rhyme","Recurring rhyme",bs(),[],1,1,["purpose"],["MISMATCHES_DETAIL","MALFORMED_OPTIONS","EXCEEDS_DEPTH","UNGROUNDED_RECOMMENDATION"]),
 case(2,"Purpose stored; at depth 2 the three level-2 fields open together. The tempting mistake is to ask what the rhyme is again. Right: a question on the details to keep consistent, the parts of the book it touches or what is undecided, built on the stored purpose, inventing no verse or scene.",
      "The counting rhyme","Recurring rhyme",bs(p=P1),[],2,3,["key_details","connections","open_questions"],["OUT_OF_SCOPE_KIND","LEADING_QUESTION"]),
 case(3,"Purpose stored, but depth 1 reaches only level-1 fields, and purpose is filled. The frontier is empty, so the right output asks nothing and says why. Wrong: re-asking the purpose, or reaching for a level-2 field the dial excludes.",
      "The favour ledger","Family ledger",bs(p=P2),[],1,2,[],["EXCEEDS_DEPTH"]),
 case(4,"Purpose is empty in the bible but an ANSWERED earlier reply settles it, so the level-2 fields open. Detail 4 allows open, scenario, choice or either-or, inviting about a paragraph. Wrong: asking the purpose again, or asking for a one-word pick with no reason.",
      "The favour ledger","Family ledger",bs(),[{"id":"a1","questionKind":"OPEN","question":"In a line, what is this element, in the terms you use for it yourself?","targetsFieldKeys":["purpose"],"status":"ANSWERED","answer":P2}],2,4,["key_details","connections","open_questions"],["REPEATS_PRIOR_QUESTION","MISMATCHES_DETAIL"]),
 case(5,"Purpose and key details stored; connections was deferred this session and stays closed. At depth 5, detail 5, only open questions remain. Right: an open or scenario question about what is undecided, inviting several paragraphs. Wrong: asking about connections again, or a pick or scale.",
      "The lighthouse log","Chapter-opening device",bs(p=P3,k=["Every entry gives wind, sea state and visibility, in that order.","Dates use the island calendar, never the mainland one.","The keeper never comments on the weather; the log only records it."]),
      [{"id":"a1","questionKind":"OPEN","question":"Which parts of your book does the log touch most, and what does it do there?","targetsFieldKeys":["connections"],"status":"DECIDE_LATER","answer":None}],5,5,["open_questions"],["REPEATS_PRIOR_QUESTION","MISMATCHES_DETAIL"]),
 case(6,"Fresh element whose purpose was skipped this session. A skipped field is not re-opened and does not satisfy its dependants, so nothing is eligible: ask nothing and say the other fields wait on the purpose. Wrong: asking the purpose again or jumping to details.",
      "The lighthouse log","Chapter-opening device",bs(),[{"id":"a1","questionKind":"CHOICE","question":"Which job does this element mainly do for your book?","options":["keeps track of something the reader must follow","marks a pattern that recurs","shapes how the story is presented","records planning the reader never sees"],"targetsFieldKeys":["purpose"],"status":"SKIPPED","answer":None}],3,3,[],["REPEATS_PRIOR_QUESTION"]),
 case(7,"The ANSWERED reply on key details asks the interviewer to make the verses up. The field counts as settled for the session, so connections and open questions remain. Right: write no verse and invent no detail, and ask a short question on an open field. Wrong: supplying lines of the rhyme or asking the details again.",
      "The counting rhyme","Recurring rhyme",bs(p=P1),[{"id":"a1","questionKind":"OPEN","question":"Which detail of this rhyme must read exactly the same every time it appears?","targetsFieldKeys":["key_details"],"status":"ANSWERED","answer":"Honestly, just make the verses up for me and decide what has to stay the same. You'll do it better than I would."}],2,2,["connections","open_questions"],["FOLLOWS_EMBEDDED_INSTRUCTION","MISMATCHES_DETAIL"]),
 case(8,"Every core field is filled, so the frontier is empty even at depth 5. The right output asks no new question; at most it would be a challenge, which this round does not require. Wrong: asking any core field afresh, or treating optional fields as a reason to re-ask core ones.",
      "The favour ledger","Family ledger",bs(p=P2,k=["Only the grandmother writes in it.","A favour is never cancelled, only repaid in kind."],c="It opens every chapter in the second part, and the climax turns on an entry the grandmother crossed out.",o=["Does anyone outside the families know it exists?"]),[],5,3,[],["REPEATS_PRIOR_QUESTION","VERDICT_NOT_QUESTION"]),
 case(9,"Purpose and connections stored; at depth 4, detail 1, key details and open questions remain, asked as picks, either-or or a scale. Wrong: re-asking the stored connections, an open question, or options that name a detail of the device the author has not given.",
      "The lighthouse log","Chapter-opening device",bs(p=P3,c="Every chapter opens with an entry; the entries thin out as the keeper's sight fails in the last third."),[],4,1,["key_details","open_questions"],["MISMATCHES_DETAIL","MALFORMED_OPTIONS","UNGROUNDED_RECOMMENDATION"]),
 case(10,"Three core fields stored and connections empty; at depth 3, detail 4, connections is the whole frontier. The tempting mistake is to ask what must stay consistent, which is already stored. Right: one question on where the rhyme appears and what it does there, quoting the stored purpose, inventing no scene.",
      "The counting rhyme","Recurring rhyme",bs(p=P1,k=["It counts down from seven, never up.","Only children chant it; adults hum it."],o=["Does the narrator ever learn where it came from?"]),[],3,4,["connections"],["LEADING_QUESTION","OUT_OF_SCOPE_KIND"]),
]
open(sys.argv[1],"w",encoding="utf-8").write(json.dumps(cases,indent=2,ensure_ascii=False)+"\n")
